'use client'

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from 'react'
import { motion, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'
import { playHoverSound, playClickSound } from '@/lib/sound'

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------

interface RadioGroupContextValue {
  value: string | undefined
  setValue: (v: string) => void
  name?: string
  groupId: string
  focusedValue: string | null
  setFocusedValue: (v: string) => void
  itemValues: string[]
  registerItem: (v: string) => void
  unregisterItem: (v: string) => void
  required?: boolean
  ariaInvalid?: boolean
}

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null)

function useRadioGroupCtx(componentName: string) {
  const ctx = useContext(RadioGroupContext)
  if (!ctx) throw new Error(`${componentName} must be used within RadioGroup`)
  return ctx
}

// ---------------------------------------------------------------------------
// RadioGroup
// ---------------------------------------------------------------------------

export interface RadioGroupProps {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  name?: string
  children?: ReactNode
  className?: string
  required?: boolean
  'aria-invalid'?: boolean
  'aria-describedby'?: string
}

export const RadioGroup = forwardRef<HTMLDivElement, RadioGroupProps>(
  (
    {
      value: valueProp,
      defaultValue,
      onValueChange,
      name,
      children,
      className,
      required,
      'aria-invalid': ariaInvalid,
      'aria-describedby': ariaDescribedby,
      ...props
    },
    ref,
  ) => {
    const isControlled = valueProp !== undefined
    const [internal, setInternal] = useState(defaultValue)
    const value = isControlled ? valueProp : internal
    const groupId = useId()
    const containerRef = useRef<HTMLDivElement>(null)

    // Track registered item values in DOM order for roving tabindex
    const [itemValues, setItemValues] = useState<string[]>([])
    const [focusedValue, setFocusedValue] = useState<string | null>(null)

    const registerItem = useCallback((v: string) => {
      setItemValues((prev) => (prev.includes(v) ? prev : [...prev, v]))
    }, [])

    const unregisterItem = useCallback((v: string) => {
      setItemValues((prev) => prev.filter((x) => x !== v))
    }, [])

    const setValue = useCallback(
      (v: string) => {
        if (!isControlled) setInternal(v)
        onValueChange?.(v)
        setFocusedValue(v)
      },
      [isControlled, onValueChange],
    )

    // Arrow key navigation (WAI-ARIA radio group pattern)
    const handleKeyDown = useCallback(
      (e: KeyboardEvent<HTMLDivElement>) => {
        const count = itemValues.length
        if (count === 0) return

        const currentIdx = focusedValue ? itemValues.indexOf(focusedValue) : -1

        let nextIdx = currentIdx

        if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
          e.preventDefault()
          nextIdx = currentIdx < 0 ? 0 : (currentIdx + 1) % count
        } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
          e.preventDefault()
          nextIdx = currentIdx < 0 ? count - 1 : (currentIdx - 1 + count) % count
        } else if (e.key === 'Home') {
          e.preventDefault()
          nextIdx = 0
        } else if (e.key === 'End') {
          e.preventDefault()
          nextIdx = count - 1
        }

        if (nextIdx !== currentIdx && nextIdx >= 0) {
          const nextValue = itemValues[nextIdx]
          if (nextValue) {
            setFocusedValue(nextValue)
            setValue(nextValue)
            // Focus the button for this value directly — indexing into a
            // `[role="radio"]` querySelectorAll would desync from
            // itemValues (which excludes disabled items) whenever a
            // disabled item sits between enabled ones.
            const button = containerRef.current?.querySelector<HTMLElement>(
              `[data-radio-value="${nextValue}"]`,
            )
            button?.focus()
          }
        }
      },
      [itemValues, focusedValue, setValue],
    )

    const ctx = useMemo<RadioGroupContextValue>(
      () => ({
        value,
        setValue,
        name,
        groupId,
        focusedValue,
        setFocusedValue,
        itemValues,
        registerItem,
        unregisterItem,
        required,
        ariaInvalid,
      }),
      [
        value,
        setValue,
        name,
        groupId,
        focusedValue,
        itemValues,
        registerItem,
        unregisterItem,
        required,
        ariaInvalid,
      ],
    )

    return (
      <RadioGroupContext.Provider value={ctx}>
        <div
          ref={(node) => {
            ;(containerRef as React.MutableRefObject<HTMLDivElement | null>).current = node
            if (typeof ref === 'function') ref(node)
            else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node
          }}
          role="radiogroup"
          aria-invalid={ariaInvalid}
          aria-describedby={ariaDescribedby}
          onKeyDown={handleKeyDown}
          className={cn('flex flex-col gap-2', className)}
          {...props}
        >
          {children}
        </div>
      </RadioGroupContext.Provider>
    )
  },
)
RadioGroup.displayName = 'RadioGroup'

// ---------------------------------------------------------------------------
// RadioItem — traveling dot (the signature)
// ---------------------------------------------------------------------------

export interface RadioItemProps {
  value: string
  label?: string
  disabled?: boolean
  className?: string
}

export const RadioItem = forwardRef<HTMLDivElement, RadioItemProps>(
  ({ value: itemValue, label, disabled, className, ...props }, ref) => {
    const {
      value,
      setValue,
      name,
      groupId,
      focusedValue,
      setFocusedValue,
      itemValues,
      registerItem,
      unregisterItem,
      required,
      ariaInvalid,
    } = useRadioGroupCtx('RadioItem')
    const reduceMotion = useReducedMotion()
    const isSelected = value === itemValue
    const id = `${groupId}-${itemValue}`

    // Register/unregister with parent for roving tabindex
    useEffect(() => {
      if (disabled) return
      registerItem(itemValue)
      return () => unregisterItem(itemValue)
    }, [itemValue, disabled, registerItem, unregisterItem])

    // Roving tabindex: exactly one item is tabbable at a time — the
    // currently keyboard-focused item once the user has interacted, else
    // the selected item, else the first registered (enabled) item. Using a
    // blanket "nothing focused yet" check here would give every enabled
    // item tabIndex 0 simultaneously, breaking Tab navigation into/out of
    // the group.
    const isTabbable =
      focusedValue !== null
        ? focusedValue === itemValue
        : itemValue === (value ?? itemValues[0])

    return (
      <div ref={ref} className={cn('flex items-center gap-3 min-h-11', className)} {...props}>
        <input
          id={id}
          type="radio"
          name={name}
          value={itemValue}
          checked={isSelected}
          disabled={disabled}
          required={required}
          readOnly
          className="sr-only"
          tabIndex={-1}
        />
        <button
          type="button"
          role="radio"
          aria-checked={isSelected}
          aria-label={label}
          data-radio-value={itemValue}
          disabled={disabled}
          tabIndex={isTabbable ? 0 : -1}
          onClick={() => {
            if (!disabled) {
              playClickSound()
              setValue(itemValue)
              setFocusedValue(itemValue)
            }
          }}
          onFocus={() => setFocusedValue(itemValue)}
          onMouseEnter={() => {
            if (!disabled) playHoverSound()
          }}
          className={cn(
            'relative flex size-5 shrink-0 items-center justify-center rounded-full border p-0 transition-[color,background-color,border-color,transform]',
            'active:scale-[0.97] motion-reduce:active:scale-100',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-2 focus-visible:ring-offset-(--color-bg)',
            'disabled:cursor-not-allowed disabled:opacity-50',
            isSelected ? 'border-(--color-fg)' : 'border-(--color-border)',
            ariaInvalid && 'border-(--color-error)',
          )}
          onPointerDown={(e) => e.preventDefault()}
        >
          {/* Traveling dot — the signature. Uses layoutId so motion/react
              animates a single element between positions. */}
          {isSelected && (
            <motion.span
              layoutId={`${groupId}-dot`}
              className="rounded-full bg-(--color-fg)"
              style={{ width: 8, height: 8 }}
              transition={reduceMotion ? { duration: 0 } : springs.moderate}
            />
          )}
        </button>
        {label && (
          <label
            htmlFor={id}
            className="min-h-11 flex items-center text-sm text-(--color-fg) select-none"
            onClick={() => {
              if (!disabled) {
                playClickSound()
                setValue(itemValue)
                setFocusedValue(itemValue)
              }
            }}
          >
            {label}
          </label>
        )}
      </div>
    )
  },
)
RadioItem.displayName = 'RadioItem'

// ---------------------------------------------------------------------------
// Preview
// ---------------------------------------------------------------------------

export function RadioGroupPreview() {
  const [value, setValue] = useState('medium')
  return (
    <div className="flex h-full w-full items-center justify-center p-6">
      <RadioGroup value={value} onValueChange={setValue} name="size">
        <RadioItem value="small" label="Small" />
        <RadioItem value="medium" label="Medium" />
        <RadioItem value="large" label="Large" />
      </RadioGroup>
    </div>
  )
}

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
